/* --- file-scope helpers (fork C, E, F and G derived the same shapes; all are
 * inlined at every call site and no out-of-line copy is emitted) --- */

static void camWorkSet(M540_CAMERAVIEW *c, Vec *target, Vec *rot, f32 *dist)
{
    if (target != NULL) {
        c->unk018 = *target;
    }
    if (rot != NULL) {
        c->unk024 = *rot;
    }
    if (dist != NULL) {
        c->unk030 = *dist;
    }
}

static void camWorkUpdate(M540_CAMERAVIEW *c)
{
    c->unk000.x = (f32)(c->unk018.x + c->unk030 * (sin(M_PI * c->unk024.y / 180.0) * cos(M_PI * c->unk024.x / 180.0)));
    c->unk000.y = (f32)(c->unk018.y + c->unk030 * -sin(M_PI * c->unk024.x / 180.0));
    c->unk000.z = (f32)(c->unk018.z + c->unk030 * (cos(M_PI * c->unk024.y / 180.0) * cos(M_PI * c->unk024.x / 180.0)));
    c->unk00C.x = (f32)(sin(M_PI * c->unk024.y / 180.0) * sin(M_PI * c->unk024.x / 180.0));
    c->unk00C.y = (f32)cos(M_PI * c->unk024.x / 180.0);
    c->unk00C.z = (f32)(cos(M_PI * c->unk024.y / 180.0) * sin(M_PI * c->unk024.x / 180.0));
}

/* fork F's spelling of the same two */
static inline void M540ViewCalc(M540_CAMERAVIEW *view)
{
    camWorkUpdate(view);
}

static inline void M540ViewSet(M540_CAMERAVIEW *view, HuVecF *center, HuVecF *rot, f32 *dist)
{
    camWorkSet(view, center, rot, dist);
}

