static inline BOOL M540SphereCheck(M540_SPHERE *a, M540_SPHERE *b)
{
    float dx = a->center.x - b->center.x;
    float dy = a->center.y - b->center.y;
    float dz = a->center.z - b->center.z;
    float r = a->radius + b->radius;

    return (HuMag2Point3D(dx, dy, dz) < HuSquare(r)) ? TRUE : FALSE;
}

static inline BOOL M540CircleCheck(M540_CIRCLE *a, M540_CIRCLE *b)
{
    float dx = a->center.x - b->center.x;
    float dy = a->center.y - b->center.y;
    float r = a->radius + b->radius;

    return (HuMag2Point2D(dx, dy) < HuSquare(r)) ? TRUE : FALSE;
}

static inline float M540AngleApproach(float cur, float target, float rate)
{
    float diff = fmod(target - cur, 360.0);
    float ret;

    if (diff < 0.0f) {
        diff += 360.0f;
    }
    if (diff > 180.0f) {
        diff -= 360.0f;
    }
    ret = fmod(cur + diff * rate, 360.0);
    if (ret < 0.0f) {
        ret += 360.0f;
    }
    return ret;
}

static inline void M540MdlPosApply(M540_OBJ *obj, float x, float y, float z)
{
    M540_MDLWORK *work = M540_MDLWORK(obj);
    Mtx mtx;
    HuVecF hook;
    float rotZ;
    s32 i;

    obj->unk160.x = x;
    obj->unk160.y = y;
    obj->unk160.z = z;
    Hu3DModelPosSet(obj->unk184, x, y - work->unk030, z);
    M540ObjMtxGet(obj, mtx);
    hook.x = mtx[0][3];
    hook.y = mtx[1][3];
    hook.z = mtx[2][3];
    Hu3DModelPosSet(work->unk064[0], hook.x + work->unk034[0].x,
                    hook.y + work->unk034[0].y - work->unk030,
                    hook.z + work->unk034[0].z);
    rotZ = 3.0f * work->unk020.x;
    for (i = 0; i < 3; i++) {
        Hu3DModelPosSet(work->unk064[i + 1], hook.x + work->unk034[i + 1].x,
                        hook.y + work->unk034[i + 1].y + (i * 8),
                        hook.z + work->unk034[i + 1].z - (i * 4));
        Hu3DModelRotSet(work->unk064[i + 1], 0.0f, 0.0f, rotZ);
    }
    if (lbl_1_bss_DC == obj) {
        lbl_1_bss_34 = x;
    }
}

static inline void M540ObjDamage(M540_OBJ *obj, s32 mode, s32 flag)
{
    M540_MDLWORK *work = M540_MDLWORK(obj);

    work->unk070 = mode;
    if (lbl_1_bss_E0[lbl_1_bss_20[3]] == obj) {
        flag = 0;
    }
    work->unk010 = flag;
    if (flag == 1) {
        lbl_1_bss_1C--;
    }
    obj->unk004 = 4;
}

/* The shared object library is an #included .c file, and both facts about
 * that matter. It is included HERE, after the prototypes and above the game
 * code, so CodeWarrior has its bodies when it compiles the game code and
 * inlines them into it -- plain -inline auto will not inline a function it has
 * not reached. And because it is an *include*, its .text is emitted as its own
 * section after this file's, which is why the library sits at the END of the
 * reference .text while being defined first. See NOTES.md. */
#include "REL/m540Dll/object.c"

